        linear-gradient(180deg, #16213f 0%, #0d1326 100%);
    }

    .image-frame img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .image-card-body,
    .details-card {
      padding: 24px;
    }

    h1,
    h2 {
      margin: 0;
      line-height: 1.1;
    }

